/* PsicoMoodle — estudos dirigidos da revisão final de 2026/2.
   Questões didáticas autorais fundamentadas nos tópicos de estudo já cadastrados.
   Roteiros originais dos professores são preservados separadamente. */
(()=>{
'use strict';
const TARGETS=['tcc','meta','grupos','social','avaliacao'];
function makeQuestion(topic,i){
 const scenario=String(topic.scenario||'Analise como o conceito se aplica a uma situação real, respeitando o contexto.').trim();
 const idea=String(topic.definition||'').trim();
 const myth=String(topic.myth||'').trim();
 return {n:i+1,topic:topic.title,section:'Revisão por assunto',
 question:'Explique '+topic.title+'.\n\nSituação: '+scenario+'\n\nComo esse conceito ajuda a entender o caso? O que ainda seria preciso saber antes de concluir?',
 options:[],answer:null,
 explanation:'Definição: '+idea+'\n\nSituação para análise: '+scenario+'\n\nUse os fatos do caso para explicar o conceito. Pense também em outras explicações possíveis. Um exemplo sozinho não permite concluir um diagnóstico ou uma causa.',
 contrast:(myth?'Evite a interpretação simplista: '+myth+'\n\n':'')+'Diferencie o que aconteceu, como o caso pode ser explicado e o que poderia ser feito.',
 points:[
 {title:'Definição do conceito',explanation:idea,example:''},
 {title:'Aplicação ao cenário',explanation:'Identifique fatos relevantes da situação e relacione-os ao conceito sem ignorar outras explicações plausíveis.',example:scenario},
 {title:'Limites e conclusão',explanation:'Considere a ética, as condições sociais e o contexto. Um exemplo isolado não basta para definir um diagnóstico ou uma causa.',example:''}
 ]};
}
const FAMILY_P2_GUIDE={"id":"familia-p2-revisao-conferida-2026","title":"Revisão comentada — Psicologia da Família (P2)","subtitle":"30 questões autorais alinhadas às aulas posteriores à P1","source":"Revisão autoral baseada no Cronograma Psicologia da Família 2026/2, aulas de 16/09 a 23/11, com P2 marcada para 25/11, e nos temas dos materiais da disciplina. As perguntas e respostas não foram atribuídas à professora e não representam gabarito oficial.","status":"adaptado","questions":[{"n":1,"section":"Divórcio e mudanças familiares","topic":"Divórcio e parentalidade","question":"Após o divórcio, o que muda na rotina da família? Quais responsabilidades dos pais continuam?","explanation":"O término de uma união conjugal não elimina as responsabilidades parentais. Há mudanças em moradia, rotinas, apoio financeiro, regras de convivência e comunicação entre responsáveis. A qualidade da reorganização depende da situação concreta, dos recursos da família, da proteção dos filhos e da capacidade de separar conflitos conjugais das tarefas de cuidado. É preciso reconhecer que configurações diversas podem oferecer vínculos seguros.","contrast":"Não presumir que todo divórcio provoque dano psicológico. O conflito persistente, a exposição de crianças a disputas e a falta de apoio merecem avaliação específica.","options":[],"answer":null},{"n":2,"section":"Divórcio e mudanças familiares","topic":"Triangulação e lealdades","question":"Na separação, os pais pedem que a criança escolha um lado. O que é triangulação e como isso pode afetá-la?","explanation":"A triangulação ocorre quando uma terceira pessoa é colocada em um conflito entre duas outras, assumindo posições de mensageiro, aliado ou mediador. A criança pode vivenciar conflito de lealdade e sentir que demonstrar afeto por um responsável significa trair o outro. Uma intervenção cuidadosa preserva sua segurança e a retira de responsabilidades que cabem aos adultos, favorecendo acordos parentais mais previsíveis.","contrast":"Não interpretar qualquer preferência da criança como manipulação. O contexto, a idade, a segurança e eventuais situações de violência precisam ser considerados.","options":[],"answer":null},{"n":3,"section":"Divórcio e mudanças familiares","topic":"Adaptação pós-separação","question":"O que ajuda uma família a se adaptar ao divórcio? O que pode dificultar essa adaptação?","explanation":"São importantes a previsibilidade das rotinas, a comunicação apropriada à idade dos filhos, a redução de conflitos entre adultos e o acesso a redes de apoio. Dificuldades econômicas, isolamento, mudanças frequentes e conflitos persistentes podem ampliar a sobrecarga. O psicólogo investiga essas condições sem presumir uma sequência obrigatória de reações ou um único modelo de família saudável.","contrast":"Não confundir existência de conflitos com problemas inevitáveis. A análise deve levar em conta a duração, a intensidade e o contexto dos conflitos.","options":[],"answer":null},{"n":4,"section":"Famílias monoparentais e recasadas","topic":"Monoparentalidade","question":"O que caracteriza uma família monoparental? Por que ela não deve ser vista como incompleta?","explanation":"Famílias monoparentais são organizadas em torno de um responsável e seus filhos ou dependentes, com possibilidades variadas de participação da família extensa e da rede de cuidado. Podem surgir por escolha, separação, morte ou outras circunstâncias. Não há déficit psicológico inerente a essa configuração; as necessidades concretas dependem de renda, tempo disponível, vínculos, apoio social e proteção.","contrast":"Evitar associar monoparentalidade à ausência de cuidado por definição. A qualidade das relações não pode ser deduzida apenas do número de responsáveis.","options":[],"answer":null},{"n":5,"section":"Famílias monoparentais e recasadas","topic":"Famílias reconstituídas","question":"Quais dificuldades podem surgir em uma família recasada?","explanation":"Novas relações podem exigir negociações sobre moradia, regras, papéis, autoridade, convivência e vínculos com familiares de uniões anteriores. Crianças e adultos podem precisar de tempos diferentes para construir confiança. A reorganização pode ser facilitada por comunicação clara, reconhecimento dos vínculos preexistentes e expectativas realistas sobre aproximação afetiva.","contrast":"Não supor que o novo companheiro ou companheira substitui imediatamente outro responsável, nem forçar afeto ou autoridade sem considerar a história dos vínculos.","options":[],"answer":null},{"n":6,"section":"Famílias monoparentais e recasadas","topic":"Fronteiras e lealdades","question":"Como podem surgir conflitos de lealdade em uma família recasada? Como lidar com os limites de cada pessoa?","explanation":"Um filho pode recear que aceitar o novo parceiro de um responsável signifique magoar o outro. A leitura sistêmica investiga alianças, papéis, comunicação e fronteiras entre subsistemas sem atribuir culpa exclusivamente à criança. A intervenção pode favorecer diálogo e responsabilidades claras entre adultos, reconhecendo que a aproximação afetiva requer tempo e respeito.","contrast":"Evitar classificar resistência inicial como patologia ou rejeição definitiva. Considerar também a segurança dos envolvidos e possíveis situações de violência.","options":[],"answer":null},{"n":7,"section":"Diversidade sexual e de gênero","topic":"Diversidade familiar","question":"Como o psicólogo deve lidar com diferentes orientações sexuais e identidades de gênero nas famílias?","explanation":"A composição da família não se limita a um arranjo heterossexual ou a papéis rígidos de gênero. Devem ser considerados vínculos, responsabilidades de cuidado, direitos, reconhecimento e contexto sociocultural. A prática psicológica não patologiza orientações sexuais nem identidades de gênero e busca compreender as demandas concretas das pessoas, inclusive os efeitos de discriminação e barreiras institucionais.","contrast":"Não transformar diferenças familiares em indicadores automáticos de disfuncionalidade. Preconceito externo pode afetar os vínculos sem definir o funcionamento de todas as famílias.","options":[],"answer":null},{"n":8,"section":"Diversidade sexual e de gênero","topic":"Revelação e acolhimento","question":"Uma pessoa fala sobre sua orientação sexual ou identidade de gênero com a família. O que deve ser considerado no acolhimento?","explanation":"A avaliação inclui segurança, qualidade dos vínculos, recursos de apoio, possíveis reações discriminatórias e autonomia da pessoa. Familiares podem precisar de informação e diálogo, mas isso não autoriza coerção ou tentativas de mudar a identidade ou orientação. O cuidado deve garantir escuta, proteção e respeito à privacidade, com encaminhamentos apropriados se houver risco.","contrast":"Não impor a revelação a familiares ou terceiros como condição de atendimento. A avaliação de riscos e a autonomia precisam orientar as decisões.","options":[],"answer":null},{"n":9,"section":"Adoção e segredos","topic":"Adoção e pertencimento","question":"O que o psicólogo precisa considerar sobre a história e os vínculos de uma família formada pela adoção?","explanation":"Adoção envolve pertencimento, reconhecimento, identidade e vínculos construídos no cotidiano. O profissional considera a história anterior da criança ou adolescente, seus recursos, os vínculos existentes e como a família responde às questões sobre origem e pertencimento. Nenhum comportamento pode ser explicado automaticamente pela adoção; é necessário investigar as condições reais de cuidado e desenvolvimento.","contrast":"Não supor que pessoas adotadas tenham necessariamente problemas de vínculo ou identidade. Evitar determinismos e estigmas.","options":[],"answer":null},{"n":10,"section":"Adoção e segredos","topic":"Segredo e privacidade","question":"Qual é a diferença entre privacidade e segredo familiar? Dê um exemplo ligado à adoção.","explanation":"Privacidade protege informações pessoais e limites legítimos de exposição. Um segredo familiar pode produzir dificuldades quando organiza proibições de falar, versões contraditórias da história, alianças e medos que afetam a confiança. O tema da origem adotiva exige comunicação sensível ao desenvolvimento e às necessidades da pessoa, sem tratar a revelação como um ato obrigatório e abrupto.","contrast":"Nem todo segredo é patológico, nem toda revelação melhora os vínculos automaticamente. O que importa é a função do silêncio e seus efeitos nas relações.","options":[],"answer":null},{"n":11,"section":"Adoção e segredos","topic":"Segredos nas relações","question":"Como um segredo mantido pela família pode afetar a comunicação e a relação entre seus membros?","explanation":"Silêncios persistentes podem aparecer em evasivas, tensões, alianças e assuntos proibidos, influenciando expectativas entre gerações. A abordagem relacional investiga quem conhece a informação, por que a mantém e quais efeitos ela produz, sem inferir a existência de segredos a partir de sintomas isolados. Segurança, consentimento e limites éticos orientam qualquer proposta de diálogo.","contrast":"Não utilizar técnicas para forçar confissões nem presumir que toda dificuldade relacional decorra de um segredo oculto.","options":[],"answer":null},{"n":12,"section":"Violência intrafamiliar e abuso sexual","topic":"Formas de violência","question":"Qual é a diferença entre conflito familiar e violência intrafamiliar? Cite formas de violência.","explanation":"Conflitos envolvem diferenças e tensões que não necessariamente incluem violação de direitos. Violência pode abranger agressões físicas, humilhações, ameaças, controle coercitivo, abuso sexual e outras práticas que geram dano e assimetria de poder. A proximidade familiar pode dificultar a busca de apoio por dependência, medo e lealdades. A prioridade profissional é reconhecer riscos e construir condições de proteção.","contrast":"Não tratar situações de coerção e abuso como divergências simétricas entre duas partes. Isso pode invisibilizar responsabilidades.","options":[],"answer":null},{"n":13,"section":"Violência intrafamiliar e abuso sexual","topic":"Proteção de crianças","question":"Como o psicólogo deve agir quando suspeita de violência contra uma criança ou adolescente?","explanation":"É necessário acolher relatos com respeito, avaliar a segurança, distinguir fatos observados de hipóteses e seguir fluxos profissionais de proteção. A atuação deve relacionar a rede competente, conforme contexto e deveres de comunicação. Perguntas sugestivas e entrevistas repetidas sem finalidade justificada podem ampliar sofrimento ou comprometer procedimentos adequados. Nenhum sinal isolado confirma ou exclui violência.","contrast":"Evitar produzir conclusões periciais a partir de um comportamento isolado ou assumir sozinho uma investigação para a qual não haja competência e respaldo técnico.","options":[],"answer":null},{"n":14,"section":"Violência intrafamiliar e abuso sexual","topic":"Abuso sexual e poder","question":"Por que é importante considerar as relações de poder e o silêncio em casos de abuso sexual na família?","explanation":"Em situações de abuso sexual, dependência, vínculo afetivo, ameaça e diferenças de poder podem dificultar o reconhecimento e a revelação. A análise psicossocial precisa priorizar a segurança e evitar responsabilizar vítimas. O trabalho pode exigir relação com saúde, assistência e órgãos de proteção, respeitando papéis profissionais distintos e a necessidade de não revitimizar a pessoa atendida.","contrast":"Não equiparar abuso a uma relação consentida entre iguais, nem propor reconciliação como solução automática para violência.","options":[],"answer":null},{"n":15,"section":"Violência intrafamiliar e abuso sexual","topic":"Acolhimento sem revitimização","question":"Como acolher alguém que relata violência familiar sem aumentar seu sofrimento?","explanation":"A escuta deve ser não julgadora, com linguagem acessível e explicitação dos limites de sigilo e das responsabilidades profissionais. É importante avaliar riscos, registrar informações com clareza e acionar redes de proteção quando cabível. O cuidado reconhece a autonomia da pessoa na medida de suas possibilidades e evita que precise repetir desnecessariamente relatos traumáticos.","contrast":"Não pressionar por detalhes irrelevantes nem confrontar a vítima com o suposto agressor em condições inseguras.","options":[],"answer":null},{"n":16,"section":"Violência intrafamiliar e abuso sexual","topic":"Pobreza e negligência","question":"Por que pobreza e falta de recursos não são, por si só, sinais de negligência familiar?","explanation":"A falta de recursos pode limitar o acesso a cuidados e serviços sem indicar, por si só, desinteresse pelos filhos. Uma avaliação responsável investiga condições materiais, possibilidades reais de cuidado, apoio disponível e violações concretas. A relação com a assistência social pode ser essencial para reduzir riscos e fortalecer vínculos, sem culpabilizar a família por desigualdades estruturais.","contrast":"Não equiparar pobreza a negligência. Também não se pode ignorar um risco real para crianças sob o argumento de que a família enfrenta dificuldades econômicas.","options":[],"answer":null},{"n":17,"section":"Luto e reorganização familiar","topic":"Luto e diversidade","question":"Por que o luto não acontece necessariamente em etapas fixas?","explanation":"As reações à perda variam conforme vínculos, circunstâncias, cultura, história e apoio disponível. Tristeza, raiva, saudade, alívio e momentos de aparente normalidade podem coexistir, sem ordem universal. O acompanhamento considera os significados da perda e as condições de vida da pessoa, evitando converter toda reação distinta em sintoma patológico.","contrast":"Não exigir que alguém atravesse cinco fases predefinidas, nem usar a ausência de choro como prova de que não houve sofrimento.","options":[],"answer":null},{"n":18,"section":"Luto e reorganização familiar","topic":"Mudanças de papéis","question":"Como uma morte pode mudar os papéis, as responsabilidades e os vínculos da família?","explanation":"A perda de um integrante pode alterar cuidado, recursos financeiros, papéis de autoridade, rotinas e comunicação. Os membros podem reagir de formas distintas e precisar de apoio em tempos diferentes. Rituais e memórias podem manter vínculos simbólicos, enquanto a família constrói novas formas de organização. O trabalho psicológico busca compreender as necessidades e os recursos disponíveis.","contrast":"Reorganização não é substituição da pessoa que morreu. Preservar a memória da relação pode coexistir com mudanças concretas na família.","options":[],"answer":null},{"n":19,"section":"Luto e reorganização familiar","topic":"Luto na infância","question":"Uma criança faz muitas perguntas após a morte de alguém próximo. Como os adultos podem acolhê-la?","explanation":"É útil oferecer explicações honestas e adequadas ao desenvolvimento, reconhecer sentimentos e preservar rotinas protetivas quando possível. A criança pode expressar seu sofrimento por fala, brincadeiras ou mudanças de comportamento; perguntas reiteradas podem ajudá-la a compreender a perda. A família também pode precisar de apoio para cuidar da criança enquanto vivencia seu próprio luto.","contrast":"Não impor explicações universais ou exigir que a criança demonstre tristeza nos mesmos termos de um adulto.","options":[],"answer":null},{"n":20,"section":"Famílias e uso problemático de substâncias","topic":"Impactos relacionais","question":"Como o uso problemático de álcool ou outras drogas pode afetar as relações familiares?","explanation":"O uso pode afetar previsibilidade das rotinas, cuidados, confiança, comunicação, finanças e responsabilidades. A perspectiva sistêmica considera como cada integrante responde ao problema e quais recursos de apoio existem, mas não atribui à família a culpa pelo uso de substâncias. O cuidado integra necessidades individuais, segurança de dependentes e acesso a serviços apropriados.","contrast":"Não reduzir todos os vínculos familiares à dependência química nem responsabilizar outros membros pela recuperação de uma pessoa.","options":[],"answer":null},{"n":21,"section":"Famílias e uso problemático de substâncias","topic":"Sobrecarga e proteção","question":"Um familiar tenta esconder o uso problemático de substâncias de outra pessoa. O que o psicólogo precisa investigar?","explanation":"Esse comportamento pode tentar evitar conflitos imediatos ou proteger outras pessoas, mas também pode aumentar sobrecarga e dificultar a busca de ajuda. O psicólogo investiga o contexto, os riscos, a segurança e as redes disponíveis antes de formular hipóteses. Podem ser construídas formas mais adequadas de apoio, comunicação e divisão de responsabilidades, respeitando a autonomia dos envolvidos.","contrast":"Não rotular automaticamente o familiar como codependente nem presumir que punições, isoladamente, resolvam uma situação complexa.","options":[],"answer":null},{"n":22,"section":"Famílias e uso problemático de substâncias","topic":"Segurança de dependentes","question":"Quais cuidados devem ser prioridade quando há crianças em uma família afetada pelo uso problemático de substâncias?","explanation":"É importante verificar condições reais de supervisão, segurança, alimentação, cuidado emocional e presença de adultos confiáveis. A existência de uso por um integrante não prova incapacidade parental; a análise deve identificar riscos observáveis e recursos de proteção. Quando necessário, a rede de saúde e proteção social precisa ser mobilizada de forma coordenada.","contrast":"Evitar tanto estigmatizar a família quanto minimizar riscos imediatos que possam comprometer crianças e dependentes.","options":[],"answer":null},{"n":23,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento clínico","question":"Quais são os primeiros cuidados no atendimento psicológico de uma família?","explanation":"O trabalho procura compreender demandas, padrões relacionais, recursos e dificuldades, definindo objetivos e condições dos encontros. É importante esclarecer quem participa, como as informações serão manejadas e os limites de sigilo. Hipóteses sobre o sistema familiar não anulam responsabilidades individuais, principalmente em situações de violência. A indicação de encontros conjuntos depende da segurança e do contexto.","contrast":"Não procurar automaticamente um integrante culpado ou transformar a teoria sistêmica em justificativa para neutralizar a gravidade de abusos.","options":[],"answer":null},{"n":24,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento hospitalar","question":"Como o psicólogo pode apoiar uma família durante uma doença grave ou internação?","explanation":"O cuidado pode apoiar a comunicação, a elaboração de mudanças de rotina e papéis, a compreensão de informações dentro dos limites éticos e o acolhimento do sofrimento. A atuação se articula à equipe multiprofissional e reconhece a autonomia da pessoa hospitalizada, sua privacidade e as necessidades de cuidadores. Também pode ser relevante em perdas e tratamentos prolongados.","contrast":"Não supor que qualquer familiar tem direito a todas as informações clínicas, nem ignorar os desejos e direitos do paciente.","options":[],"answer":null},{"n":25,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento escolar","question":"Uma escola culpa a estrutura familiar pelas dificuldades de um aluno. Como o psicólogo deve avaliar a situação?","explanation":"É preciso considerar o contexto escolar, condições de ensino, desenvolvimento, relações e recursos da família, sem supor causalidade a partir de uma configuração específica. O profissional pode construir diálogo com responsáveis e educadores e promover ações compatíveis com a finalidade do trabalho, preservando sigilo e evitando estigmas sobre famílias diversas.","contrast":"Não confundir correlação com causa, nem usar a expressão 'família desestruturada' como explicação técnica suficiente.","options":[],"answer":null},{"n":26,"section":"Atendimento familiar em diferentes contextos","topic":"Contexto jurídico","question":"Qual é a diferença entre atender famílias na clínica e no contexto jurídico?","explanation":"A atuação no sistema de justiça pode envolver avaliação, orientação técnica ou perícia, segundo finalidades e atribuições delimitadas. Exige procedimentos adequados, atenção aos direitos dos envolvidos, fontes de informação proporcionais e comunicação de limites das conclusões. Isso não significa, por si só, psicoterapia familiar; objetivos e deveres profissionais variam conforme a demanda institucional.","contrast":"Não emitir conclusões sobre vínculos familiares com base em preferências pessoais ou em informações insuficientes.","options":[],"answer":null},{"n":27,"section":"Atendimento familiar em diferentes contextos","topic":"Assistência social","question":"Qual é o papel do atendimento psicológico a famílias na assistência social?","explanation":"Esse contexto enfatiza direitos, acesso a serviços, redes de apoio, vulnerabilidades do território e fortalecimento de vínculos. O psicólogo considera fatores estruturais e recursos comunitários em relação com equipes e políticas públicas, evitando reduzir dificuldades sociais a características individuais. Quando necessário, são construídos encaminhamentos junto a serviços de saúde, educação e proteção.","contrast":"Não confundir pobreza com falha moral da família, nem substituir ações de garantia de direitos por diagnósticos psicológicos sem fundamento.","options":[],"answer":null},{"n":28,"section":"Questões integradoras da P2","topic":"Caso: divórcio e recasamento","question":"Uma adolescente acha que gostar do padrasto é trair o pai. Como entender esse conflito com os conceitos da disciplina?","explanation":"O caso mobiliza temas de divórcio, recasamento, lealdades e limites entre papéis familiares. Pode haver conflito de lealdade, mas essa hipótese precisa ser investigada por meio da escuta e do contexto. A intervenção busca reduzir exigências de tomada de partido, reconhecer a história dos vínculos e favorecer acordos de convivência respeitosos. O objetivo é proteger a autonomia afetiva da adolescente.","contrast":"Não atribuir o problema somente à adolescente nem forçar aproximação afetiva para provar que o recasamento foi bem-sucedido.","options":[],"answer":null},{"n":29,"section":"Questões integradoras da P2","topic":"Caso: proteção e cuidado","question":"Uma família vive conflitos, uso problemático de substâncias e suspeita de violência contra uma criança. Qual deve ser a prioridade?","explanation":"A prioridade é verificar e promover segurança e proteção, mobilizando serviços competentes e respeitando protocolos profissionais. O cuidado com o uso de substâncias pode exigir acompanhamento especializado, mas não substitui respostas a situações de violência. Uma leitura sistêmica considera padrões relacionais e redes disponíveis sem distribuir igualmente a responsabilidade por agressões. A intervenção deve reduzir revitimização e garantir atenção às necessidades da criança.","contrast":"Não propor reconciliação imediata ou terapia conjunta como solução automática quando houver riscos de violência.","options":[],"answer":null},{"n":30,"section":"Questões integradoras da P2","topic":"Caso: luto e hospital","question":"Após uma morte, os familiares reagem de formas diferentes. Como o psicólogo deve acolher essas diferenças?","explanation":"O psicólogo pode acolher reações distintas, identificar necessidades individuais e ajudar na comunicação familiar, respeitando diferentes tempos de elaboração. A perda pode alterar papéis e responsabilidades e coexistir com rituais e memórias que preservam o pertencimento. No contexto hospitalar, é essencial relacionar ações com a equipe e respeitar limites de informação e a autonomia das pessoas envolvidas.","contrast":"Não classificar uma reação como correta e outra como errada apenas porque uma pessoa chora e outra permanece silenciosa.","options":[],"answer":null}]};
const GRUPOS_P2_GUIDE={"id":"grupos-p2-revisao-conferida-2026","title":"Revisão comentada — Psicologia de Grupos (P2)","subtitle":"13 questões autorais do conteúdo posterior à P1","source":"Revisão autoral elaborada a partir do plano e cronograma 'GruposI-357.docx', que registra P1 em 06/10 e P2 em 24/11; temas: Moreno, Psicodrama/Sociodrama, Rogers, grupos comunitários e grupos virtuais. Não é roteiro nem gabarito do professor.","status":"adaptado","questions":[{"n":1,"section":"Moreno — Psicodrama","topic":"Psicodrama e ação","question":"Qual a diferença entre falar sobre um problema e dramatizá-lo em uma proposta de Psicodrama?","explanation":"O Psicodrama de Jacob Levy Moreno utiliza a ação dramática para explorar relações, papéis e experiências. A dramatização permite experimentar cenas e alternativas de resposta com mediação e cuidado, enquanto uma conversa exclusivamente verbal privilegia a descrição e a elaboração por palavras. O recurso dramático não substitui escuta, contexto ou segurança: sua utilidade depende dos objetivos do grupo e do manejo de quem facilita.","contrast":"Não interpretar a encenação como reprodução literal dos fatos nem transformar qualquer representação em diagnóstico. A dramatização é recurso de investigação e elaboração.","options":[],"answer":null},{"n":2,"section":"Moreno — Psicodrama","topic":"Etapas psicodramáticas","question":"Descreve a função do aquecimento, da dramatização e do compartilhamento numa sessão psicodramática.","explanation":"O aquecimento prepara o grupo para a atividade, favorecendo disponibilidade e envolvimento; a dramatização coloca em ação a situação escolhida, com definição de personagens, papéis e recursos; o compartilhamento permite que os participantes expressem ressonâncias e integrem a experiência. A sequência ajuda a criar um enquadre coerente, mas cada etapa demanda adequação ao contexto, aos objetivos e ao nível de segurança grupal.","contrast":"Compartilhar não equivale a emitir julgamentos sobre a atuação do protagonista. A etapa não deve transformar a vivência alheia em alvo de avaliações depreciativas.","options":[],"answer":null},{"n":3,"section":"Moreno — Psicodrama","topic":"Papéis e espontaneidade","question":"O que são papéis e espontaneidade em Moreno? Como esses conceitos ajudam a analisar uma situação grupal?","explanation":"Papéis dizem respeito às formas de atuação que emergem nas relações e nos contextos, não a essências fixas de personalidade. A espontaneidade está relacionada à possibilidade de responder de modo criativo e adequado a situações novas ou antigas. Em uma dinâmica, observar os papéis permite compreender expectativas e alternativas de ação; favorecer espontaneidade não significa impor exposição ou eliminar regras.","contrast":"Não confundir espontaneidade com impulsividade ou ausência de responsabilidade, nem reduzir uma pessoa a um único papel no grupo.","options":[],"answer":null},{"n":4,"section":"Moreno — Sociodrama","topic":"Psicodrama e Sociodrama","question":"Em que diferem Psicodrama e Sociodrama quanto ao foco de análise e ao problema representado?","explanation":"No Psicodrama, frequentemente o foco parte de experiências e conflitos de um protagonista, situados em relações concretas. No Sociodrama, o foco recai sobre questões coletivas e papéis sociais compartilhados, como conflitos institucionais e situações comunitárias. Em ambos, a dramatização permite explorar posições e relações, respeitando o enquadre, os objetivos e a participação voluntária.","contrast":"Não presumir que Sociodrama seja apenas teatro escolar ou que o Psicodrama tenha sempre um único formato clínico. O contexto e a finalidade importam.","options":[],"answer":null},{"n":5,"section":"Moreno — Psicodrama","topic":"Inversão de papéis","question":"Uma dinâmica propõe que duas pessoas representem a posição uma da outra. O que a inversão de papéis pode favorecer e quais são seus limites?","explanation":"A inversão de papéis pode ampliar a perspectiva dos participantes ao permitir experimentar, de modo simbólico, posições diferentes nas relações. Ela pode evidenciar expectativas, conflitos e possibilidades de comunicação, especialmente quando acompanhada de reflexão e compartilhamento. Sua realização deve respeitar consentimento, condição emocional e segurança dos envolvidos, evitando exposição indevida ou pressão sobre pessoas vulneráveis.","contrast":"Representar o papel de outra pessoa não prova que se compreende plenamente sua experiência. Não se deve usar essa técnica para forçar concordância ou justificar violência.","options":[],"answer":null},{"n":6,"section":"Rogers — Grupos de encontro","topic":"Empatia e escuta","question":"Como a empatia e a escuta podem favorecer as relações num grupo de encontro inspirado em Carl Rogers?","explanation":"Empatia implica tentar compreender o mundo do outro a partir de seu ponto de vista, sem perder a distinção entre a experiência própria e a do outro. A escuta respeitosa pode facilitar expressão de sentimentos, reconhecimento de diferenças e confiança. O facilitador não precisa concordar com tudo o que é dito; busca criar condições para que os participantes se expressem e assumam responsabilidade por suas escolhas.","contrast":"Empatia não é aprovação automática nem aconselhamento padronizado. Ouvir com atenção é diferente de minimizar um conflito ou exigir confissão de sentimentos.","options":[],"answer":null},{"n":7,"section":"Rogers — Grupos de encontro","topic":"Aceitação e congruência","question":"Diferencia consideração positiva incondicional e congruência no trabalho com grupos.","explanation":"A consideração positiva incondicional consiste em reconhecer o valor da pessoa sem condicionar esse reconhecimento à conformidade de seus comportamentos ou opiniões. Congruência envolve autenticidade e coerência entre vivência, consciência e expressão do facilitador. No grupo, essas atitudes podem favorecer um ambiente menos defensivo e mais aberto à aprendizagem relacional, sem eliminar limites éticos e regras de convivência.","contrast":"Aceitar a pessoa não significa validar comportamentos prejudiciais. Congruência não autoriza despejar reações pessoais sem considerar o efeito sobre os demais participantes.","options":[],"answer":null},{"n":8,"section":"Rogers — Grupos de encontro","topic":"Facilitador e não diretividade","question":"Qual é o papel do facilitador em um grupo de encontro? O que significa trabalhar de maneira não diretiva?","explanation":"O facilitador busca oferecer condições de acolhimento, escuta e comunicação para que o próprio grupo possa elaborar seus temas e relações. A não diretividade evita impor respostas prontas ou controlar de forma autoritária o conteúdo da experiência, mas não exige passividade diante de riscos. Há responsabilidade pelo enquadre, pelo respeito às pessoas e pelo manejo adequado de situações de agressão ou vulnerabilidade.","contrast":"Não diretividade não é abandono do grupo. A responsabilidade técnica por segurança, limites e condições de participação permanece.","options":[],"answer":null},{"n":9,"section":"Rogers — Grupos de encontro","topic":"Conflito e autenticidade","question":"Em um grupo, um participante minimiza repetidamente seus próprios erros para preservar a imagem de competência. Como compreender isso pela ótica rogeriana?","explanation":"A pessoa pode perceber uma distância entre sua experiência efetiva e a imagem idealizada que tenta manter diante dos outros. Essa incongruência pode favorecer defesas e dificuldade de reconhecer falhas sem sentir ameaça ao próprio valor. Um ambiente de empatia e aceitação pode facilitar maior contato com a experiência e a possibilidade de falar de responsabilidades sem humilhação. Essa interpretação é hipótese, não diagnóstico.","contrast":"Aceitação não consiste em fingir que o erro não ocorreu nem em exigir exposição pública. A pessoa pode reconhecer limites e reparar danos sem ser desqualificada.","options":[],"answer":null},{"n":10,"section":"Grupos comunitários","topic":"Objetivos e participação","question":"Quais cuidados ajudam a diferenciar uma prática grupal comunitária de uma simples reunião de pessoas?","explanation":"Um trabalho grupal comunitário pode favorecer escuta, pertencimento, construção coletiva de demandas e participação na busca de recursos e direitos. Precisa considerar território, desigualdades, instituições e quem efetivamente participa das decisões. O grupo não é definido somente pelo número de integrantes: são importantes objetivos, relações, tarefas e formas de organização. O psicólogo atua de maneira situada, valorizando saberes e recursos locais.","contrast":"Não tratar a comunidade como homogênea nem substituir suas decisões pelas preferências do profissional. Participação precisa ser real, não apenas simbólica.","options":[],"answer":null},{"n":11,"section":"Grupos virtuais","topic":"Vínculo e mediação digital","question":"Quais prelacionaridades dos grupos virtuais devem ser consideradas ao analisar comunicação, pertencimento e participação?","explanation":"Ambientes digitais podem facilitar o encontro de pessoas distantes e ampliar acesso, mas também modificam pistas comunicacionais, turnos de fala, privacidade e condições de participação. Diferenças de acesso à internet, exposição pública e possibilidade de gravações exigem cuidados específicos. O grupo continua construindo normas, expectativas e posições relacionais; a tecnologia altera o meio, não elimina os processos grupais.","contrast":"Não concluir que um vínculo virtual é sempre superficial ou que o uso de plataformas garante participação igualitária. É necessário observar práticas e contexto.","options":[],"answer":null},{"n":12,"section":"Integração da P2","topic":"Moreno e Rogers em contraste","question":"Compara uma intervenção inspirada no Psicodrama de Moreno e outra inspirada nos grupos de encontro de Rogers.","explanation":"Em uma situação de comunicação difícil, o Psicodrama pode utilizar dramatização, papéis e inversão de posições para explorar alternativas na ação. Um grupo de encontro rogeriano tende a favorecer compreensão da experiência por escuta empática, autenticidade e consideração positiva. Ambas são propostas de trabalho com relações, mas partem de recursos e ênfases distintas; a escolha depende de objetivos, participantes e segurança.","contrast":"Não apresentar uma proposta como superior em qualquer situação. O método adequado deve ser definido pela demanda e pelo enquadre profissional.","options":[],"answer":null},{"n":13,"section":"Integração da P2","topic":"Caso de grupo presencial e virtual","question":"Um grupo universitário presencial cria um canal online e surgem exclusões e mal-entendidos. Como relacionar conteúdos da P2 para formular hipóteses e possibilidades de intervenção?","explanation":"Uma leitura considera os papéis assumidos, as normas de participação, os efeitos da mediação digital e possíveis conflitos entre subgrupos. Estratégias podem incluir pactos de comunicação, escuta das pessoas excluídas e atividades reflexivas ou dramáticas adequadas ao contexto. A perspectiva rogeriana ajuda a valorizar empatia e autenticidade; Moreno oferece recursos para experimentar posições e respostas. Nenhuma proposta deve ser imposta sem avaliar adesão e segurança.","contrast":"Não atribuir conflitos exclusivamente à plataforma nem interpretar silêncio online como prova de desinteresse ou rejeição de colegas.","options":[],"answer":null}]};
const SOCIAL_P3_GUIDE={"id":"social-p3-revisao-integrada-2026","title":"Revisão comentada — Psicologia Social I (P3)","subtitle":"15 questões autorais para integração das perspectivas e temas contemporâneos","source":"Revisão autoral baseada em materiais de Psicologia Social I cadastrados no site: Martín-Baró, Psicologia Sócio-Histórica, identidade, representações sociais, preconceito, interseccionalidade, epistemicídio, infância/políticas públicas e tecnologias digitais. O plano disponível no acervo tem dados divergentes de turma/semestre e não comprova sozinho o recorte da P3. O roteiro não é oficial e os conteúdos exatos devem ser confirmados com o professor.","status":"adaptado","questions":[{"n":1,"section":"Integração das perspectivas","topic":"Paradigmas de Psicologia Social","question":"Compara as perspectivas sociológica, psicológica, sócio-histórica e crítica na compreensão de um fenômeno coletivo.","explanation":"As perspectivas diferem quanto às perguntas e escalas de análise. Uma abordagem sociológica pode enfatizar representações, instituições e relações sociais; a psicológica pode examinar processos de categorização e atitudes; a sócio-histórica considera a constituição histórica e material dos sujeitos; a crítica problematiza poder, desigualdades e produção ideológica. Ao analisar uma situação concreta, é preciso explicitar o referencial usado em vez de misturar conceitos sem critério.","contrast":"Não reduzir todas as abordagens a uma mesma definição do indivíduo. A perspectiva adotada orienta o que conta como problema, evidência e possibilidade de intervenção.","options":[],"answer":null},{"n":2,"section":"Identidade e representação","topic":"Identidade em Stuart Hall","question":"Como Stuart Hall ajuda a compreender identidade e diferenças nas sociedades contemporâneas?","explanation":"A identidade não é compreendida como uma essência estável e imune a mudanças históricas. Em sociedades marcadas por transformações culturais e relações de poder, pertencimentos e posições de sujeito podem se deslocar e ser construídos nas relações sociais. Uma pessoa pode vivenciar identificações múltiplas, por vezes contraditórias, conforme os contextos. Esse olhar ajuda a analisar conflitos de pertencimento sem reduzir identidades a características individuais fixas.","contrast":"Não interpretar multiplicidade de identificações como doença ou ausência de identidade. Trata-se de uma reflexão sociocultural sobre constituição dos sujeitos.","options":[],"answer":null},{"n":3,"section":"Identidade e representação","topic":"Representações sociais","question":"O que são representações sociais e como podem ser observadas em narrativas coletivas, como no filme Narradores de Javé?","explanation":"Representações sociais são formas compartilhadas e socialmente elaboradas de compreender objetos, acontecimentos e grupos. Circulam na comunicação e nas práticas cotidianas, tornando temas familiares e orientando percepções. No caso de narrativas sobre a história de uma comunidade, versões e disputas por reconhecimento podem expressar interesses e posições sociais diferentes. A análise observa como sentidos são produzidos, legitimados e contestados.","contrast":"Não confundir representação social com opinião privada de uma única pessoa ou com cópia transparente da realidade. É necessário observar circulação, ancoragens e contextos.","options":[],"answer":null},{"n":4,"section":"Identidade e representação","topic":"Estigma e preconceito","question":"Diferencia estereótipo, preconceito, discriminação e estigma em uma situação de exclusão social.","explanation":"Estereótipos são generalizações atribuídas a pessoas ou grupos; preconceitos envolvem avaliações e atitudes frequentemente negativas; discriminação refere-se a práticas de tratamento desigual; estigma designa processos de desvalorização social de atributos e identidades em relações específicas. Esses processos podem ocorrer conjuntamente, mas não são sinônimos. A Psicologia Social investiga como se sustentam em normas e instituições, além de experiências individuais.","contrast":"Não supor que todo estereótipo leva à mesma ação nem restringir o preconceito a uma opinião isolada: relações estruturais e consequências concretas importam.","options":[],"answer":null},{"n":5,"section":"Psicologia sócio-histórica e crítica","topic":"Sujeito e condições históricas","question":"Como a Psicologia Sócio-Histórica relaciona constituição da subjetividade, trabalho e condições materiais de vida?","explanation":"A subjetividade é compreendida como constituída em processos históricos e sociais, envolvendo linguagem, relações de trabalho, instituições e contradições das condições materiais. Experiências aparentemente pessoais podem ter mediações coletivas e políticas. A análise busca compreender processos concretos sem apagar a agência do sujeito. Isso permite questionar explicações que atribuem desigualdades apenas a mérito, esforço individual ou características naturais.","contrast":"Não tratar a pessoa como simples reflexo passivo do contexto. A relação entre sujeito e sociedade envolve atividade, contradições e transformação.","options":[],"answer":null},{"n":6,"section":"Psicologia sócio-histórica e crítica","topic":"Psicologia da Libertação","question":"Quais são os objetivos da Psicologia da Libertação de Ignacio Martín-Baró e como ela problematiza a atuação profissional?","explanation":"A proposta de Martín-Baró exige que a Psicologia considere a realidade histórica das populações latino-americanas, suas lutas e a produção social do sofrimento. A atuação é chamada a questionar explicações que legitimam opressões e a contribuir com processos de conscientização, participação e transformação social. O conhecimento psicológico não é neutro em relação a valores e interesses, exigindo posicionamento ético refletido e diálogo com experiências concretas.","contrast":"Não confundir Psicologia da Libertação com propaganda ou mera defesa de opinião pessoal. Ela demanda investigação rigorosa de realidade, relações de poder e condições de vida.","options":[],"answer":null},{"n":7,"section":"Psicologia sócio-histórica e crítica","topic":"Democracia formal e efetiva","question":"Diferencia democracia formal e democracia efetiva no contexto da análise de Martín-Baró.","explanation":"A democracia formal refere-se à existência de regras, instituições, eleições e direitos reconhecidos juridicamente. A democracia efetiva exige condições concretas para o exercício desses direitos e participação na vida social. Quando desigualdades materiais, violência ou exclusão impedem o acesso a direitos, pode haver distância entre promessa institucional e experiência cotidiana. A análise psicossocial considera estruturas e processos subjetivos que sustentam essa distância.","contrast":"Não concluir que eleições ou normas jurídicas são irrelevantes; a distinção aponta que a existência formal de direitos não garante, por si, seu exercício real.","options":[],"answer":null},{"n":8,"section":"Psicologia sócio-histórica e crítica","topic":"Fatalismo latino-americano","question":"O que Martín-Baró entende por fatalismo latino-americano e por que não se deve reduzi-lo a traço de personalidade?","explanation":"O fatalismo envolve formas de compreender o destino social como inevitável, podendo favorecer resignação diante de adversidades. Na perspectiva crítica, ele deve ser situado em condições históricas de dominação e desigualdade e na construção de sentidos que desestimulam a ação coletiva. Não é uma característica natural do povo latino-americano. Intervenções exigem reconhecer possibilidades reais de ação, barreiras concretas e experiência dos grupos envolvidos.","contrast":"Não culpar populações em situação de desigualdade por suas condições. Uma explicação somente psicológica pode ocultar relações estruturais que limitam escolhas.","options":[],"answer":null},{"n":9,"section":"Psicologia sócio-histórica e crítica","topic":"Desideologização","question":"O que significa desideologização na Psicologia Social e como ela se diferencia da simples correção de informações falsas?","explanation":"Desideologização busca tornar visíveis relações entre discursos, interesses, condições sociais e modos naturalizados de explicar a realidade. Envolve examinar como certos sentidos legitimam injustiças e impedem compreender alternativas de ação. Não se limita a apontar erros factuais: inclui investigar quem produz mensagens, como circulam e quais efeitos têm nas práticas e relações de poder. O trabalho requer diálogo crítico e valorização da experiência concreta.","contrast":"Não apresentar desideologização como impor uma verdade pronta a outras pessoas. O processo exige reflexão, evidências e participação.","options":[],"answer":null},{"n":10,"section":"Marcadores sociais e diferenças","topic":"Interseccionalidade","question":"Como a interseccionalidade pode aprofundar a análise de desigualdades de raça, gênero e classe?","explanation":"A interseccionalidade considera que diferentes relações de poder se articulam e podem produzir experiências específicas que não são explicadas pela simples soma de categorias isoladas. Uma situação de exclusão no trabalho, por exemplo, pode envolver gênero, raça, classe e condições migratórias de formas inseparáveis. O pesquisador precisa observar a posição concreta de sujeitos e instituições em vez de usar marcadores como rótulos automáticos.","contrast":"Não tratar identidades como causas inevitáveis de comportamento. Marcadores são relevantes conforme história, contexto e relações de poder.","options":[],"answer":null},{"n":11,"section":"Marcadores sociais e diferenças","topic":"Epistemicídio","question":"O que é epistemicídio e qual sua relação com racismo, sexismo e produção do conhecimento?","explanation":"Epistemicídio descreve processos de silenciamento, deslegitimação ou destruição de saberes e modos de conhecer de grupos historicamente subordinados. Em uma análise crítica, pode ocorrer quando instituições tratam certas tradições e sujeitos como incapazes de produzir conhecimento válido, reproduzindo hierarquias coloniais e de gênero. Investigar suas formas exige analisar critérios de legitimidade, circulação de autores e vozes ausentes nos currículos.","contrast":"Não basta citar diversidade superficialmente: é preciso examinar como instituições estabelecem autoridade, acesso e reconhecimento de conhecimentos.","options":[],"answer":null},{"n":12,"section":"Marcadores sociais e diferenças","topic":"Infância e políticas públicas","question":"Como políticas públicas podem influenciar a produção social das experiências de infância e juventude?","explanation":"As experiências de crianças e jovens são atravessadas por condições de moradia, educação, saúde, proteção, raça, gênero e território. Políticas públicas podem ampliar direitos e recursos, mas sua implementação desigual pode reproduzir exclusões. A Psicologia Social investiga como instituições definem problemas, classificam populações e produzem efeitos nas trajetórias, sem reduzir a infância a uma etapa abstrata e igual para todos.","contrast":"Não inferir que todas as crianças em um mesmo grupo social vivem experiências idênticas, nem explicar desigualdades apenas por escolhas familiares.","options":[],"answer":null},{"n":13,"section":"Tecnologias da informação","topic":"Algoritmos e subjetividade","question":"Como algoritmos de recomendação e plataformas digitais podem influenciar formas de participação, percepção social e polarização?","explanation":"Sistemas de recomendação selecionam e ordenam conteúdos conforme objetivos de plataforma e sinais de interação, podendo ampliar a exposição repetida a certos temas e perspectivas. Isso pode interagir com vieses, identidades, redes de pertencimento e disputas políticas, mas não elimina a ação das pessoas. Uma análise psicossocial investiga interesses econômicos, circulação de mensagens, efeitos da infraestrutura e práticas concretas de uso.","contrast":"Não afirmar que todo algoritmo cria automaticamente uma bolha fechada nem que as pessoas perdem completamente autonomia. Efeitos dependem do desenho da plataforma e do contexto.","options":[],"answer":null},{"n":14,"section":"Integração crítica da P3","topic":"Observação e evidências","question":"Como relacionar uma observação de campo a conceitos da Psicologia Social sem transformar impressões em conclusões generalizantes?","explanation":"É necessário delimitar problema e contexto, explicitar o procedimento de observação e distinguir episódios registrados de hipóteses interpretativas. Depois, conceitos como identidade, representação, ideologia e marcadores sociais podem ajudar a problematizar o fenômeno, desde que as relações sejam justificadas. Limites da amostra, possíveis vieses e implicações éticas devem ser reconhecidos. Uma narrativa teoricamente coerente não substitui evidência empírica suficiente.","contrast":"Não apresentar casos isolados como prova universal nem tratar a escolha de um referencial como autorização para ignorar dados discordantes.","options":[],"answer":null},{"n":15,"section":"Integração crítica da P3","topic":"Caso de desigualdade e comunicação","question":"Uma campanha digital responsabiliza indivíduos isoladamente por problemas estruturais. Como integrar fatalismo, ideologia e processos de comunicação na análise?","explanation":"Pode-se investigar quais causas são omitidas, como a campanha constrói responsabilidade e que possibilidades de ação apresenta às pessoas atingidas. Martín-Baró ajuda a pensar naturalização da desigualdade e fatalismo; a análise das plataformas observa alcance, repetição e segmentação; perspectivas de interseccionalidade ajudam a considerar impactos distintos. O objetivo é formular hipóteses sustentadas em dados e identificar tensões entre explicações individuais e condições sociais.","contrast":"Não pressupor automaticamente a intenção de todos os envolvidos ou efeitos iguais entre públicos. A análise exige evidências, atenção ao contexto e cuidado com simplificações.","options":[],"answer":null}]};
const AVALIACAO_P3_GUIDE={"id":"avaliacao-p3-revisao-conferida-2026","title":"Revisão comentada — Avaliação Psicológica (P3)","subtitle":"15 questões autorais de devolutiva, contextos de atuação e ética","source":"Revisão autoral delimitada pelo cronograma da turma 357/2026-02 da professora Maísa dos Santos Rigoni: após a P2 de 29/10, constam devolutiva (03/11), contexto organizacional (05/11), hospitalar (10/11), forense (12/11), pacientes trans (17/11), ética (19/11) e palestra COF (24/11), com P3 em 26/11. Não é estudo dirigido oficial nem gabarito docente. Materiais das palestras ainda podem precisar de complementação.","status":"adaptado","questions":[{"n":1,"section":"Entrevista de devolução","topic":"Objetivos da devolutiva","question":"Qual é a finalidade da entrevista de devolução em um processo de avaliação psicológica e o que a diferencia de uma simples entrega de resultados?","explanation":"A devolutiva procura comunicar e contextualizar os achados de maneira compreensível, acolhendo dúvidas e relacionando informações à demanda inicial e às condições da pessoa avaliada. É uma etapa de diálogo que pode orientar encaminhamentos e cuidados, não apenas uma leitura de escores ou entrega de documentos. A comunicação deve deixar claros os limites dos dados, evitar rótulos e respeitar a autonomia, a compreensão e as necessidades da pessoa.","contrast":"Não reduzir a entrevista a uma comunicação unilateral ou a uma listagem de resultados. É preciso verificar compreensão e evitar conclusões que ultrapassem o alcance da avaliação.","options":[],"answer":null},{"n":2,"section":"Entrevista de devolução","topic":"Comunicação acessível","question":"Uma pessoa recebe resultados psicológicos com termos técnicos que não compreende. Como o profissional pode reorganizar a devolutiva?","explanation":"O psicólogo pode começar pela pergunta que motivou a avaliação, traduzir termos técnicos em linguagem acessível, utilizar exemplos pertinentes e oferecer espaço para a pessoa expressar dúvidas e reações. Também precisa distinguir resultados de hipóteses e explicar limitações e recomendações proporcionais. Adaptar linguagem não significa simplificar indevidamente os achados; significa torná-los compreensíveis no contexto de vida de quem os recebe.","contrast":"Evitar termos alarmistas ou diagnósticos sem fundamentação. Também não basta perguntar 'entendeu?' sem oferecer condições reais para compreensão.","options":[],"answer":null},{"n":3,"section":"Entrevista de devolução","topic":"Acolhimento de reações","question":"Uma pessoa discorda de parte dos resultados e se emociona durante a devolutiva. Que atitudes são adequadas?","explanation":"Reações de surpresa, dúvida ou sofrimento podem surgir diante de informações sobre si. É importante acolher sem invalidar, escutar a perspectiva da pessoa, explicar os critérios do processo e considerar se há aspectos que exigem esclarecimento. O profissional deve preservar um espaço dialógico e não usar a autoridade técnica para impedir perguntas. Eventuais orientações de cuidado precisam respeitar os limites do processo e as necessidades concretas da pessoa avaliada.","contrast":"Não transformar discordância em resistência patológica nem utilizar a devolutiva para impor uma interpretação única. O diálogo pode enriquecer a contextualização dos resultados.","options":[],"answer":null},{"n":4,"section":"Entrevista de devolução","topic":"Informação e confidencialidade","question":"Como lidar com o pedido de terceiros para receber informações detalhadas de uma devolutiva psicológica?","explanation":"A comunicação de resultados deve respeitar finalidade, consentimento e limites de confidencialidade, além das condições legais e profissionais aplicáveis. É essencial verificar quem solicita a informação, qual seu papel e qual conteúdo é necessário compartilhar. O cuidado ético pode exigir comunicações distintas conforme se trate de pessoa avaliada, responsável legal ou instituição solicitante, sempre evitando exposição de informações desnecessárias.","contrast":"Não presumir que familiares, gestores ou instituições tenham acesso irrestrito ao conteúdo da avaliação. Direitos da pessoa avaliada e regras profissionais orientam o compartilhamento.","options":[],"answer":null},{"n":5,"section":"Avaliação em contexto organizacional","topic":"Finalidades e contexto","question":"Que tipos de demanda podem levar à avaliação psicológica em uma organização e quais cuidados a diferenciam da avaliação clínica?","explanation":"No âmbito organizacional, avaliações podem ser solicitadas para seleção, orientação ou desenvolvimento profissional, conforme finalidade e normas aplicáveis. O psicólogo precisa delimitar a demanda, usar procedimentos pertinentes e comunicar conclusões proporcionais à função solicitada. A análise deve considerar aspectos do trabalho, condições organizacionais e riscos de discriminação, sem converter dados de avaliação em julgamentos globais da pessoa.","contrast":"Não transpor automaticamente conclusões de um contexto clínico para decisões sobre emprego. Um resultado não deve ser usado fora da finalidade para a qual foi obtido.","options":[],"answer":null},{"n":6,"section":"Avaliação em contexto organizacional","topic":"Sigilo e uso de dados","question":"Uma empresa pede acesso integral às respostas e informações íntimas de candidatos após uma avaliação. Como proceder?","explanation":"Deve-se examinar a finalidade legítima da solicitação, os limites da informação necessária para a decisão e as exigências éticas de confidencialidade. A pessoa avaliada não perde seus direitos de privacidade por estar em processo seletivo. A comunicação profissional deve se restringir ao que é pertinente e autorizado pelo enquadre e pelas normas, evitando exposição de dados sensíveis e uso discriminatório.","contrast":"Não entregar dados íntimos apenas porque a organização contratou o serviço. O vínculo contratual não elimina obrigações éticas para com a pessoa avaliada.","options":[],"answer":null},{"n":7,"section":"Avaliação no contexto hospitalar","topic":"Condições de hospitalização","question":"Como a avaliação psicológica no hospital pode adaptar procedimentos às condições clínicas e ao ambiente de cuidado?","explanation":"O ambiente hospitalar apresenta variações de tempo disponível, condições físicas, presença de familiares e prioridades clínicas. O psicólogo precisa delimitar a pergunta de avaliação, considerar estado de saúde, fadiga, medicamentos, compreensão e privacidade e relacionar informações pertinentes com a equipe. O planejamento é flexível, mas mantém fundamentação e respeito à autonomia, sem aplicar instrumentos indiscriminadamente quando a condição da pessoa não permite.","contrast":"Não confundir dificuldades decorrentes de doença, dor ou exaustão com características psicológicas permanentes. As condições do exame influenciam a interpretação.","options":[],"answer":null},{"n":8,"section":"Avaliação no contexto hospitalar","topic":"Equipe multiprofissional","question":"Que cuidados orientam o compartilhamento de informações psicológicas com outros profissionais de uma equipe de saúde?","explanation":"O trabalho multiprofissional exige comunicação suficiente para o cuidado, mas não compartilhamento irrestrito. O psicólogo considera finalidade, sigilo, necessidade clínica e compreensão da pessoa atendida, registrando informações de forma apropriada. Questões emocionais podem estar relacionadas à adesão, à comunicação e às redes de apoio, devendo ser situadas no contexto do adoecimento e da organização do cuidado.","contrast":"Não tratar a equipe como autorização genérica para divulgar histórias íntimas. Deve-se compartilhar apenas o necessário para ações de cuidado apropriadas.","options":[],"answer":null},{"n":9,"section":"Avaliação psicológica no contexto forense","topic":"Finalidade e delimitação","question":"Por que a avaliação psicológica forense exige cuidado especial com demanda, finalidade e limites das conclusões?","explanation":"No contexto forense, a avaliação responde a questões definidas em um procedimento ou solicitação jurídica e pode produzir efeitos sobre direitos e decisões institucionais. O profissional deve delimitar suas atribuições, utilizar informações pertinentes, distinguir dados de hipóteses e comunicar limites. A função avaliativa não é idêntica à relação terapêutica, e expectativas de sigilo e destinatários precisam ser explicados no enquadre.","contrast":"Não confundir o papel do avaliador com o de terapeuta, juiz ou advogado. A Psicologia oferece informações técnicas, não decide sozinha questões jurídicas.","options":[],"answer":null},{"n":10,"section":"Avaliação psicológica no contexto forense","topic":"Entrevistas e fontes","question":"Quais são os riscos de concluir algo em uma avaliação forense a partir de uma única declaração ou observação isolada?","explanation":"Uma informação isolada pode estar incompleta, ser influenciada por contexto, memória, expectativas ou finalidade do procedimento. A avaliação precisa de critérios técnicos, integração de fontes pertinentes e explicitação das limitações de cada evidência. Quando informações são divergentes, o profissional deve relatar de forma responsável a diferença observada, sem inventar certeza ou antecipar juízo que não possa fundamentar.","contrast":"Não usar um teste ou entrevista como detector automático de verdade e mentira. Limitações metodológicas precisam ser consideradas em qualquer conclusão.","options":[],"answer":null},{"n":11,"section":"Avaliação de pessoas trans","topic":"Acolhimento não patologizante","question":"Que princípios devem orientar a avaliação psicológica de pessoas trans?","explanation":"A avaliação precisa respeitar identidade de gênero, nome social, autonomia, história e demanda apresentada, sem supor que ser trans constitui transtorno mental. É fundamental considerar contexto de vida, barreiras de acesso, experiências de discriminação e necessidades reais de cuidado. Procedimentos e comunicação devem ser apropriados à finalidade e livres de estereótipos, com consentimento e respeito à privacidade.","contrast":"Não buscar 'provar' ou invalidar uma identidade de gênero por critérios pessoais do profissional. A atuação deve seguir normas éticas e técnicas aplicáveis.","options":[],"answer":null},{"n":12,"section":"Avaliação de pessoas trans","topic":"Demandas e diversidade","question":"Uma pessoa trans procura atendimento e relata ansiedade relacionada à rejeição familiar. Como evitar uma interpretação inadequada na avaliação?","explanation":"O profissional deve distinguir a identidade da pessoa das situações de sofrimento que relata. Pode investigar experiências de rejeição, ameaças, redes de apoio, condições materiais e sintomas apresentados, sem inferir causalidade automática ou reduzir toda demanda à identidade de gênero. A avaliação considera singularidades e proteção, com encaminhamentos proporcionais e diálogo sobre prioridades e objetivos.","contrast":"Não atribuir sofrimento inerente à condição trans nem ignorar a contribuição da discriminação e do contexto social. Identidade e demanda clínica não são sinônimos.","options":[],"answer":null},{"n":13,"section":"Ética e responsabilidade profissional","topic":"Consentimento e limites","question":"Quais cuidados éticos devem ser explicitados antes de uma avaliação psicológica em contextos diferentes?","explanation":"É importante apresentar finalidade, procedimentos, uso das informações, destinatários, limites da confidencialidade e possíveis consequências da avaliação com linguagem compreensível. O enquadre precisa considerar a autonomia e condições específicas da pessoa, além das obrigações institucionais e legais. Em contextos organizacionais, hospitalares e forenses, a clareza sobre papéis e destinatários é especialmente relevante.","contrast":"Não presumir que um mesmo termo de consentimento resolva todas as situações. O profissional deve adaptar a comunicação à demanda e às regras aplicáveis.","options":[],"answer":null},{"n":14,"section":"Ética e responsabilidade profissional","topic":"Limites da competência","question":"Uma instituição solicita que o psicólogo produza conclusões fora da sua competência e sem dados suficientes. Como deveria responder?","explanation":"O psicólogo precisa delimitar o que pode ser inferido tecnicamente com base nos procedimentos realizados e comunicar limites de maneira clara. Uma demanda institucional não autoriza especulações, uso inadequado de instrumentos ou afirmações sem respaldo. Quando necessário, pode propor outras fontes, encaminhamentos ou recusar conclusões incompatíveis com evidências e atribuições profissionais. A responsabilidade ética permanece mesmo diante de pressões externas.","contrast":"Não produzir laudos categóricos para satisfazer a instituição, nem confundir opinião pessoal com resultado de avaliação fundamentada.","options":[],"answer":null},{"n":15,"section":"Questão integradora da P3","topic":"Caso ético em contextos distintos","question":"Compara como a mesma preocupação com privacidade se manifesta na devolutiva, em uma empresa, no hospital e em uma avaliação forense.","explanation":"Em todos os contextos, devem ser respeitados direitos da pessoa avaliada, finalidade da avaliação e limites de confidencialidade. Na devolutiva, importa comunicar resultados de modo compreensível; na empresa, restringir a informação relevante à decisão; no hospital, compartilhar com a equipe apenas o necessário ao cuidado; no forense, explicar destinatários e responsabilidades específicas do procedimento. A análise ética depende do enquadre e das normas vigentes em cada contexto.","contrast":"Não existe autorização universal para divulgação integral dos dados. A mesma regra geral de proteção se concretiza de modos diferentes conforme demanda, vínculo e finalidade.","options":[],"answer":null}]};
function apply(db){
 const guides=window.PSICO_GUIDES||(window.PSICO_GUIDES={});
 guides.familia=guides.familia||[];
 if(!guides.familia.some(g=>g.id===FAMILY_P2_GUIDE.id))guides.familia.unshift(FAMILY_P2_GUIDE);
 guides.grupos=guides.grupos||[];
 if(!guides.grupos.some(g=>g.id===GRUPOS_P2_GUIDE.id))guides.grupos.unshift(GRUPOS_P2_GUIDE);
 guides.social=guides.social||[];
 if(!guides.social.some(g=>g.id===SOCIAL_P3_GUIDE.id))guides.social.unshift(SOCIAL_P3_GUIDE);
 guides.avaliacao=guides.avaliacao||[];
 if(!guides.avaliacao.some(g=>g.id===AVALIACAO_P3_GUIDE.id))guides.avaliacao.unshift(AVALIACAO_P3_GUIDE);
 const curated=window.PSICO_FINAL_EXAMS?.curated;
 if(typeof curated!=='function'||!db?.topics)return;
 for(const subject of TARGETS){
  const id='final-2026-2-'+subject;
  const topics=curated(db,subject);
  if(!topics?.length)continue;
  guides[subject]=guides[subject]||[];
  if(subject==='meta')guides[subject]=guides[subject].filter(x=>x.id!==id);
  if(guides[subject].some(x=>x.id===id))continue;
  guides[subject].unshift({id,title:'Estudo dirigido — revisão final de 2026/2',
   subtitle:topics.length+' conceitos comentados com exemplos e limites de interpretação',
   source:'Roteiro didático autoral organizado com base nos tópicos dos materiais cadastrados na disciplina. Não reproduz literalmente um estudo dirigido do professor nem substitui a leitura dos arquivos.',
   status:'adaptado',questions:topics.map(makeQuestion)});
 }
}
window.PSICO_FINAL_GUIDES={apply,makeQuestion};
})();